import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-06-04 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-06-04 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-06-04T00:00:00.000Z","updated":"2019-06-07T00:00:00.000Z","tags":["Ceph","Distributed Storage","OSD","CRUSH Algorithm","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-04_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-06-04_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-06-04_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function n(s,e,a,_,p,g){return i(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年6月4日</p><p><strong>参会人员</strong>： [请填写参会人员姓名]</p><p><strong>会议主题</strong>： Ceph 项目进展讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 对象类支持</strong></p><ul><li>[姓名] 正在准备 Chrome 对象类支持，涉及重构和移除大写互斥锁，并尝试在 <code>alien</code> 中运行对象类。</li><li>由于 [姓名] 正在休假，集成性能测试到 CI 的进展缓慢，需要加快进度。</li><li>计划重写所有对象类，仅对支持 RBD 的子集进行操作，并定义函数类型，返回对应的功能类型。</li></ul><p><strong>2. Alien 存储和输入缓冲区工厂</strong></p><ul><li>[姓名] 正在开发 <code>alien</code> 存储解决方案，并专注于输入缓冲区工厂的概念。</li><li>通过分析 SPDK 的 BDF 和 NVMe 驱动程序文档，确定了连续性的实际需求。</li><li>输入缓冲区工厂的概念已经提交 PR，并扩展了文档。</li></ul><p><strong>3. IO 环 (IOU Ring)</strong></p><ul><li>[姓名] 认为使用 IOU Ring 将有助于减少开销，但仍然需要执行内存复制以保持用户空间应用程序和内核之间的隔离。</li></ul><p><strong>4. Peering 代码</strong></p><ul><li>[姓名] 上周合并了 crimson peering 功能，现在可以启动多个 OSD，并执行一些操作，例如创建 PG 和拉取池。</li><li>下一步是实施基于日志的恢复和填充。</li></ul><p><strong>5. 复制支持</strong></p><ul><li>[姓名] 认为复制支持比对象类支持更重要，因为它将影响接口设计。</li><li>[姓名] 将查看 [姓名] 的 PR28395，并开始实施复制支持。</li></ul><p><strong>6. CStar 数据源实现</strong></p><ul><li>[姓名] 解决了 CStar 消息测试的长期问题，并提交了 PR 以支持当前的对齐和填充要求。</li><li>[姓名] 认为我们需要一个统一的接口，该接口不需要区分是否使用基于 DPDK 的堆栈或 POSIX 堆栈。</li></ul><p><strong>7. 其他事项</strong></p><ul><li>[姓名] 将参加 11 月在加州洛杉矶举行的 3DBenchmarks 提交和 Sister Summit。</li><li>[姓名] 将联系 CDB 团队，以讨论重构或更改 <code>read exactly</code> 或 <code>consume</code> 接口。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>[姓名] 将继续开发 <code>alien</code> 存储解决方案和输入缓冲区工厂。</li><li>[姓名] 将实施复制支持。</li><li>[姓名] 将与 CDB 团队讨论接口更改。</li><li>[姓名] 将参加 11 月在加州洛杉矶举行的 3DBenchmarks 提交和 Sister Summit。</li></ul>',21)])])}const c=t(r,[["render",n]]);export{d as __pageData,c as default};
